const countries={kz:{code:'KZ',name:'Kazakhstan',label:'NATIONAL TRAINING',value:'650,000+',unit:'students received AI training certificates',text:'AI-Sana creates an opportunity to connect national training with course-level evaluation.',model:'National AI-Sana training through courses and certificates.',question:'Do skills transfer into independent learning in Kazakh and Russian?',note:'Official administrative report of 2025 results. Certificates measure programme reach, not retained skills.',source:13},ru:{code:'RU',name:'Russia',label:'UNIVERSITY-LEVEL PRACTICE',value:'≈87%',unit:'reported AI use in learning',text:'High uptake in the surveyed institutions makes actual student practice an important starting point.',model:'Student use across selected leading universities.',question:'How representative is uptake beyond these campuses?',note:'More than 4,000 students at 10 leading universities, March–April 2025. Not a national probability sample.',source:14},uk:{code:'UK',name:'United Kingdom',label:'SECTOR GUIDANCE + LOCAL RULES',value:'94%',unit:'used GenAI to help with assessed work',text:'Shared principles encourage AI literacy and assessment adaptation, with rules applied at course level.',model:'Sector principles alongside institutional and course policies.',question:'Are rules consistent and clear in students’ day-to-day study?',note:'HEPI 2026 report, 1,054 full-time UK undergraduates. The survey measures use, not cheating or better learning.',source:12,extra:15},us:{code:'US',name:'United States',label:'INSTITUTIONAL PILOTS',value:'ASU',unit:'an example of managed AI experimentation',text:'Approved projects give staff and students room to test specific educational uses.',model:'Institutional pilots and managed AI access at Arizona State University.',question:'Which findings transfer to other universities and languages?',note:'ASU is an institutional example, not a description of every US university. The separate physics trial adds experimental evidence.',source:16,extra:7}};
