const steps=[{title:'Start with your own attempt.',description:'The learner explains what they tried before requesting support. This makes the reasoning visible and gives a tutor something to respond to.',student:'I think this solution works, but I am unsure about step two.',support:'Write down why you chose that step before asking for a hint.',type:'STUDENT'}, {title:'Ground the response in course material.',description:'Retrieve an approved passage from the course. Teachers curate these materials, and retrieval still needs checking.',student:'Which part of our course explains this idea?',support:'Find the relevant definition or worked example in the approved materials.',type:'COURSE'}, {title:'Offer a hint that keeps the thinking active.',description:'The tutor asks a question and cites a relevant passage. The student checks the citation and completes the reasoning.',student:'Can you help me find the next step without giving the answer?',support:'What does the definition tell you about the relationship between these quantities?',type:'TUTOR'}, {title:'Check understanding without AI.',description:'Use a fresh problem without assistance to see whether the learner can explain and apply the idea independently.',student:'I will try a new question on my own and explain each step.',support:'Compare your reasoning with the course rubric, then discuss any gaps with a teacher.',type:'REVIEW'}];
